function App() {
  // On the server we cannot know the client's clock, so render a stable
  // placeholder for the first render (matches server output), then fill it in.
  const [now, setNow] = useState(null);
  useEffect(() => {
    setNow(new Date().toLocaleTimeString());
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Client time</h2>
      <p>{now === null ? 'Loading…' : now}</p>
      <small style={{ color: '#6b7280' }}>First render shows the same 'Loading…' the server would; useEffect updates it after hydration.</small>
    </div>
  );
}

