solution.code:
function App() {
  // Render a stable default first (server will produce the same thing),
  // then compute the real greeting on the client after hydration.
  const [greeting, setGreeting] = useState('Hello');
  useEffect(() => {
    const hour = new Date().getHours();
    setGreeting(hour < 12 ? 'Good morning' : 'Good evening');
  }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      {/* If you truly cannot avoid a benign diff (e.g. a timestamp),
          suppressHydrationWarning silences it for THIS element only: */}
      <h2 suppressHydrationWarning>{greeting}</h2>
    </div>
  );
}

function useIsHydrated() {
  const [hydrated, setHydrated] = useState(false);
  useEffect(() => {
    // Runs only on the client, after hydration completes.
    setHydrated(true);
  }, []);
  return hydrated;
}

function App() {
  const hydrated = useIsHydrated();
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>Viewport widget</h2>
      {hydrated
        ? <p>Width: {window.innerWidth}px</p>
        : <p>Measuring…</p>}
    </div>
  );
}

